output_text:
[
  {
    "id": "pedestrian_only_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves flank both sides of the shopper.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_single_file",
    "text": "A shopper must not push a cart from an open area into a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "parking_implies_pedestrian_aisle_visit",
    "text": "If a shopper sets down the cart in an open aisle, they are obliged to proceed on foot into a single-file aisle before exiting.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "openAisle": {
          "gt": [
            "freeWidthH",
            2
          ]
        }
      },
      "events": {
        "setDownCartInOpenAisle": {
          "pre": {
            "and": [
              "openAisle",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "setDownCartInOpenAisle",
      "discharge": "enterSingleFileOnFoot"
    }
  },
  {
    "id": "return_to_cart_after_hand_pick",
    "text": "After taking an item by hand in a single-file shelf aisle, the shopper is obliged to return and pick the cart back up.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "handPickInSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "handPickInSingleFileAisle",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "no_cartless_open_aisle_travel",
    "text": "A shopper may not walk without the cart through ordinary open aisles, except when the move is directly entering or leaving a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "cartlessOpenToOpenMove": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE",
              {
                "not": "singleFileAisle"
              }
            ]
          },
          "post": {
            "not": "singleFileAisle"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessOpenToOpenMove"
    }
  },
  {
    "id": "cart_required_for_ordinary_shelf_service",
    "text": "Shelf interactions outside single-file shelf aisles must be done while holding or pushing the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "ordinaryShelfAccess": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "ordinaryShelfAccess",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "park_cart_only_in_wide_cross_aisles",
    "text": "A shopper may set down the cart only in a wide cross-aisle with enough horizontal and vertical clearance.",
    "abstraction": {
      "state_properties": {
        "wideCrossAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "wideCrossAisle"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_handover_at_shelf_front",
    "text": "Picking up or setting down the cart is prohibited at shelf-front cells, so cart handovers must happen away from shelves.",
    "abstraction": {
      "state_properties": {
        "shelfFront": "adjShelf"
      },
      "events": {
        "setDownCartAtShelfFront": {
          "pre": {
            "and": [
              "shelfFront",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCartAtShelfFront": {
          "pre": {
            "and": [
              "shelfFront",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "setDownCartAtShelfFront",
          "pickUpCartAtShelfFront"
        ]
      }
    }
  }
]
